// Regenerates src/lib/mobile-ready.generated.ts: the public paths that have a mobile (app) page, found from the folders src/app/(m)/m/<path>/page.tsx.
//   node tools/sync-mobile-ready.mjs
// A phone or tablet gets /m<path> for every path in the list (see src/lib/device.ts and src/proxy.ts). Never edit the generated file by hand.

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const base = path.join(root, "src/app/(m)/m");
const found = [];
const walk = (dir, rel) => {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    if (!e.isDirectory() || e.name.startsWith("_") || e.name.startsWith("(")) continue;
    const r = `${rel}/${e.name}`;
    if (fs.existsSync(path.join(dir, e.name, "page.tsx"))) found.push(r);
    walk(path.join(dir, e.name), r);
  }
};
walk(base, "");
found.sort();
const out = `// GENERATED by tools/sync-mobile-ready.mjs from the folders of src/app/(m)/m. Do not edit by hand.\nexport const MOBILE_PAGES: string[] = ${JSON.stringify(found, null, 2)};\n`;
fs.writeFileSync(path.join(root, "src/lib/mobile-ready.generated.ts"), out);
console.log(`${found.length} mobile page(s):`, found.join(" ") || "(none yet)");
